            box.Size =
                new Size(
                    220,
                    23
                );


            box.DropDownStyle =
                ComboBoxStyle.DropDownList;


            box.DropDownWidth =
                420;
        }


        private void CreatePresetColorRow(
            Label label,
            string text,
            int y,
            NumericUpDown box1,
            NumericUpDown box2,
            NumericUpDown box3,
            NumericUpDown box4)
        {
            label.Location =
                new Point(
                    20,
                    y
                );


            label.AutoSize =
                true;


            label.Text =
                text;


            NumericUpDown[] boxes =
            {
                box1,
                box2,
                box3,
                box4
            };


            for (
                int i = 0;
                i < boxes.Length;
                i++)
            {
                boxes[i].Location =
                    new Point(
                        20 +
                        (
                            i *
                            73
                        ),
                        y + 25
                    );


                boxes[i].Size =
                    new Size(
                        65,
                        23
                    );


                boxes[i].Maximum =
                    65535;
            }
        }


